const fs=require('fs');
const workerPath='_worker.js';
let source=fs.readFileSync(workerPath,'utf8');
const marker='// bare-review-photo-lightbox-v1';
if(!source.includes(marker)){
source+=`\n\n${marker}\nconst barePhotoLightboxStyle='<style id="bare-photo-lightbox-style">.review-media img:not(.bare-review-video *){cursor:zoom-in}.bare-photo-lightbox{position:fixed;inset:0;z-index:260;display:grid;place-items:center;padding:28px;background:rgba(0,0,0,.92);opacity:0;visibility:hidden;pointer-events:none;transition:opacity .18s ease,visibility .18s ease}.bare-photo-lightbox.is-open{opacity:1;visibility:visible;pointer-events:auto}.bare-photo-lightbox-stage{position:relative;display:grid;place-items:center;width:100%;height:100%}.bare-photo-lightbox-img{display:block;max-width:min(1120px,calc(100vw - 120px));max-height:calc(100svh - 72px);width:auto;height:auto;object-fit:contain}.bare-photo-lightbox-close,.bare-photo-lightbox-nav{position:absolute;z-index:2;display:grid;place-items:center;border:1px solid rgba(255,255,255,.55);border-radius:50%;background:rgba(0,0,0,.66);color:#fff;cursor:pointer}.bare-photo-lightbox-close{top:20px;right:20px;width:50px;height:50px;font:300 34px/1 Arial,sans-serif}.bare-photo-lightbox-nav{top:50%;width:54px;height:54px;font:300 34px/1 Arial,sans-serif;transform:translateY(-50%)}.bare-photo-lightbox-prev{left:22px}.bare-photo-lightbox-next{right:22px}.bare-photo-lightbox-nav[hidden]{display:none}.bare-photo-lightbox-count{position:absolute;left:50%;bottom:18px;z-index:2;min-width:54px;padding:7px 10px;background:rgba(0,0,0,.62);color:#fff;text-align:center;font:900 11px/1 InterDisplay,sans-serif;transform:translateX(-50%)}@media(max-width:860px){.bare-photo-lightbox{padding:14px}.bare-photo-lightbox-img{max-width:calc(100vw - 28px);max-height:calc(100svh - 92px)}.bare-photo-lightbox-close{top:12px;right:12px;width:46px;height:46px}.bare-photo-lightbox-nav{width:46px;height:46px}.bare-photo-lightbox-prev{left:10px}.bare-photo-lightbox-next{right:10px}}</style>';\nconst barePhotoLightboxMarkup='<aside class="bare-photo-lightbox" aria-hidden="true" aria-label="리뷰 사진 확대"><div class="bare-photo-lightbox-stage"><img class="bare-photo-lightbox-img" alt="확대된 리뷰 사진"><button class="bare-photo-lightbox-close" type="button" aria-label="확대 사진 닫기">×</button><button class="bare-photo-lightbox-nav bare-photo-lightbox-prev" type="button" aria-label="이전 사진">‹</button><button class="bare-photo-lightbox-nav bare-photo-lightbox-next" type="button" aria-label="다음 사진">›</button><span class="bare-photo-lightbox-count"></span></div></aside>';\nconst barePhotoLightboxScript='<script id="bare-photo-lightbox-script">(()=>{const box=document.querySelector(".bare-photo-lightbox"),image=box?.querySelector(".bare-photo-lightbox-img"),prev=box?.querySelector(".bare-photo-lightbox-prev"),next=box?.querySelector(".bare-photo-lightbox-next"),count=box?.querySelector(".bare-photo-lightbox-count");let items=[],index=0,scrollYBefore=0;function draw(){if(!image||!items.length)return;index=(index+items.length)%items.length;image.src=items[index].src;image.alt=items[index].alt||"확대된 리뷰 사진";const multiple=items.length>1;if(prev)prev.hidden=!multiple;if(next)next.hidden=!multiple;if(count){count.hidden=!multiple;count.textContent=(index+1)+" / "+items.length}}function open(target){const card=target.closest(".review-card"),photos=card?Array.from(card.querySelectorAll(".review-media img")).filter(img=>!img.closest(".bare-review-video-frame")&&!/\\.(mp4|webm|mov)(?:[?#]|$)/i.test(img.getAttribute("src")||"")):[];if(!photos.length)return;items=photos.map(img=>({src:img.currentSrc||img.src,alt:img.alt||"리뷰 사진"}));index=Math.max(0,photos.indexOf(target));scrollYBefore=scrollY;box?.classList.add("is-open");box?.setAttribute("aria-hidden","false");document.documentElement.style.overflow="hidden";draw()}function close(){box?.classList.remove("is-open");box?.setAttribute("aria-hidden","true");document.documentElement.style.overflow="";image?.removeAttribute("src");requestAnimationFrame(()=>scrollTo({top:scrollYBefore,behavior:"auto"}))}function move(delta){index+=delta;draw()}document.addEventListener("click",event=>{const target=event.target.closest(".review-media img");if(!target||target.closest(".bare-review-video-frame"))return;event.preventDefault();event.stopPropagation();open(target)},true);box?.querySelector(".bare-photo-lightbox-close")?.addEventListener("click",event=>{event.preventDefault();event.stopPropagation();close()});prev?.addEventListener("click",event=>{event.preventDefault();event.stopPropagation();move(-1)});next?.addEventListener("click",event=>{event.preventDefault();event.stopPropagation();move(1)});box?.addEventListener("click",event=>{if(event.target===box||event.target.classList.contains("bare-photo-lightbox-stage"))close()});addEventListener("keydown",event=>{if(!box?.classList.contains("is-open"))return;if(event.key==="Escape")close();if(event.key==="ArrowLeft"&&items.length>1)move(-1);if(event.key==="ArrowRight"&&items.length>1)move(1)})})();<\\/script>';\nconst barePhotoLightboxBase=patchHtml;\npatchHtml=function(html){return barePhotoLightboxBase(html).replace('</head>',barePhotoLightboxStyle+'</head>').replace('</body>',barePhotoLightboxMarkup+barePhotoLightboxScript+'</body>')};\n`;
fs.writeFileSync(workerPath,source);
}
for(const path of ['.github/add-review-photo-lightbox.cjs','.github/workflows/add-review-photo-lightbox.yml'])if(fs.existsSync(path))fs.unlinkSync(path);
